var nextCard = null;
var switchingCard = null;
var nextCardPanel = document.getElementById("switchCardPanel");
var nextCardInput = document.getElementById("nextCardInput");

function setSwitchFeedback(message) {
    var target = document.getElementById("switchCardFeedback");
    if (target) target.textContent = message;
}

function hideSwitchCardPanel() {
    nextCardPanel.hidden = true;
}

function readNextCard() {
    var username = nextCardInput.value.replace(/[\s\u200b-\u200d]/g, "").replace(/[٠-٩]/g, function (d) { return String(d.charCodeAt(0) - 1632); }).replace(/[۰-۹]/g, function (d) { return String(d.charCodeAt(0) - 1776); });
    nextCardInput.value = username;
    if (!username) { setSwitchFeedback("أدخل رقم الكرت الجديد أولاً."); return null; }
    if (username === document.getElementById("username").textContent.trim()) { setSwitchFeedback("هذا هو الكرت المتصل حالياً."); return null; }
    return {username:username, speed:getSavedSpeed(), statusChecks:0};
}

function prepareNextCard(event) {
    if (event) event.preventDefault();
    if (switchingCard) return;
    var card = readNextCard();
    if (!card) return;
    nextCard = card;
    if (loggedIn) scheduleStatusQuery();
    setSwitchFeedback("تم تجهيز الكرت التالي. سيتم تسجيل دخوله تلقائياً عند انتهاء الكرت الحالي ما دامت الصفحة مفتوحة.");
}

